// Facebook 2026 UI labels used by the fake site, English and Polish. Sources: docs/research/dom-chrome.md §10
// (EN snapshots, PL strings decoded from Facebook's pl_PL bundles) and dom-feed.md §5.1.

const plPlural = (n, one, few, many) => {
  if (n === 1) return one;
  const m10 = n % 10;
  const m100 = n % 100;
  return m10 >= 2 && m10 <= 4 && !(m100 >= 12 && m100 <= 14) ? few : many;
};

